import "jsr:@supabase/functions-js/edge-runtime.d.ts";

const U=Deno.env.get("SUPABASE_URL")??"";
const K=Deno.env.get("SUPABASE_ANON_KEY")??"";
const O=Deno.env.get("OPENAI_API_KEY")??"";
const GH=Deno.env.get("GITHUB_TOKEN")??Deno.env.get("GITHUB_PAT")??Deno.env.get("GITHUB_REPO_TOKEN")??"";
const REPO=Deno.env.get("AI_EDITORIAL_GITHUB_REPO")??"Syasu-pixel/my-site";
const TEXT_MODEL=Deno.env.get("OPENAI_EDITOR_MODEL")??"gpt-5.6-luna";
const REVIEW_MODEL=Deno.env.get("OPENAI_REVIEW_MODEL")??"gpt-5.6-luna";
const IMAGE_MODEL=Deno.env.get("OPENAI_IMAGE_MODEL")??"gpt-image-2";
const IMAGE_QUALITY=(Deno.env.get("OPENAI_IMAGE_QUALITY")??"high").toLowerCase();
const TEMPLATE="articles/short-ground-leakage-basic.html";
const SOURCE_SLUG="short-ground-leakage-basic";
const PAGES_PROJECT=Deno.env.get("AI_EDITORIAL_CLOUDFLARE_PAGES_PROJECT")??"denkicontrol-preview";
function branchAlias(branch:string){return String(branch||"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"")}
function cloudflarePreview(branch:string,articlePath:string){const alias=branchAlias(branch);const path=String(articlePath||"").replace(/^\/+/,"");return `https://${alias}.${PAGES_PROJECT}.pages.dev/${path}`}
const H={"Access-Control-Allow-Origin":"*","Access-Control-Allow-Headers":"authorization, apikey, content-type, x-client-info, x-supabase-api-version","Access-Control-Allow-Methods":"POST, OPTIONS","Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store"};
const J=(b:unknown,s=200)=>new Response(JSON.stringify(b),{status:s,headers:H});
const esc=(s:unknown)=>String(s??"").replace(/[&<>\"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;"}[c]??c));

function outputText(b:any){if(typeof b?.output_text==="string")return b.output_text;for(const i of Array.isArray(b?.output)?b.output:[])if(i?.type==="message")for(const p of Array.isArray(i?.content)?i.content:[])if(p?.type==="output_text"&&typeof p.text==="string")return p.text;return ""}
async function rpc(raw:string,n:string,a:any){const r=await fetch(`${U}/rest/v1/rpc/${n}`,{method:"POST",headers:{Authorization:raw,apikey:K,"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify(a)});const t=await r.text();if(!r.ok)throw new Error(`${n} ${r.status}: ${t.slice(0,800)}`);return t?JSON.parse(t):{}}
const patch=(raw:string,id:string,s:string,e:string|null=null)=>rpc(raw,"ai_editorial_command_patch",{p_command_id:id,p_status:s,p_last_error:e,p_mark_started:false});
const add=(raw:string,id:string,ev:any[])=>rpc(raw,"ai_editorial_command_add_events",{p_command_id:id,p_events:ev});
const checkpoint=(raw:string,id:string,stage:string,state:any)=>rpc(raw,"ai_editorial_builder_checkpoint",{p_command_id:id,p_stage:stage,p_state:state});
async function event(raw:string,id:string,stage:string,summary:string,state="BUILDING",severity="info",evidence:any[]=[]){const allowed=new Set(["info","low","medium","high","blocker"]);const normalized=severity==="warning"?"medium":allowed.has(severity)?severity:"medium";try{return await add(raw,id,[{event_id:crypto.randomUUID(),job_id:`command-${id}`,role:"system",provider:"article-builder-v4",event_type:"status",summary,evidence,severity:normalized,state,created_at:new Date().toISOString(),discussion:{command_id:id,stage},availability:{primary_provider:"article-builder-v4",status:state==="NEEDS_HUMAN"?"waiting-human":"online"}}])}catch(e){console.error("article-builder event log failed",{id,stage,severity:normalized,error:e instanceof Error?e.message:String(e)});return null}}

async function oa(payload:any){if(!O)throw new Error("OPENAI_API_KEY missing");const r=await fetch("https://api.openai.com/v1/responses",{method:"POST",headers:{Authorization:`Bearer ${O}`,"Content-Type":"application/json"},body:JSON.stringify(payload)});const t=await r.text();if(!r.ok)throw new Error(`OpenAI ${r.status}: ${t.slice(0,900)}`);return JSON.parse(t)}
function b64ToBytes(b64:string){const bin=atob(b64),out=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)out[i]=bin.charCodeAt(i);return out}
function utf8ToB64(s:string){const bytes=new TextEncoder().encode(s);let bin="";for(let i=0;i<bytes.length;i+=0x8000)bin+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return btoa(bin)}
function b64ToUtf8(s:string){return new TextDecoder().decode(b64ToBytes(s.replace(/\n/g,"")))}
async function gh(path:string,init:RequestInit={}){if(!GH)throw new Error("GITHUB_REPO_TOKEN missing");const r=await fetch(`https://api.github.com/repos/${REPO}${path}`,{...init,headers:{Authorization:`Bearer ${GH}`,Accept:"application/vnd.github+json","X-GitHub-Api-Version":"2022-11-28","Content-Type":"application/json",...(init.headers||{})}});const t=await r.text();let b:any={};try{b=t?JSON.parse(t):{}}catch{b={raw:t}}if(!r.ok)throw new Error(`GitHub ${r.status} ${path}: ${t.slice(0,900)}`);return b}
async function getRepoFile(path:string,ref="main"){return gh(`/contents/${path}?ref=${encodeURIComponent(ref)}`)}
async function getTemplate(){const x=await getRepoFile(TEMPLATE);return b64ToUtf8(String(x.content||""))}
async function ensureBranch(branch:string){try{await gh(`/git/ref/heads/${encodeURIComponent(branch)}`);return}catch{}const base=await gh(`/git/ref/heads/main`);await gh(`/git/refs`,{method:"POST",body:JSON.stringify({ref:`refs/heads/${branch}`,sha:base.object.sha})})}
async function putFile(branch:string,path:string,contentB64:string,msg:string){let sha:string|undefined;try{const x=await getRepoFile(path,branch);sha=x.sha}catch{}const body:any={message:msg,content:contentB64,branch};if(sha)body.sha=sha;return gh(`/contents/${path}`,{method:"PUT",body:JSON.stringify(body)})}
async function openPr(branch:string,title:string,body:string){const owner=REPO.split("/")[0];const existing=await gh(`/pulls?state=open&head=${encodeURIComponent(owner+":"+branch)}`);if(Array.isArray(existing)&&existing[0])return existing[0];return gh(`/pulls`,{method:"POST",body:JSON.stringify({title,head:branch,base:"main",body})})}

async function makeImage(prompt:string,size="1536x1024"){const quality=["low","medium","high","auto"].includes(IMAGE_QUALITY)?IMAGE_QUALITY:"high";const r=await fetch("https://api.openai.com/v1/images/generations",{method:"POST",headers:{Authorization:`Bearer ${O}`,"Content-Type":"application/json"},body:JSON.stringify({model:IMAGE_MODEL,prompt,size,quality,output_format:"png"})});const t=await r.text();if(!r.ok)throw new Error(`Image API ${r.status}: ${t.slice(0,900)}`);const b=JSON.parse(t),x=b?.data?.[0];if(typeof x?.b64_json==="string")return x.b64_json;if(typeof x?.url==="string"){const ir=await fetch(x.url);if(!ir.ok)throw new Error(`image download ${ir.status}`);const ab=new Uint8Array(await ir.arrayBuffer());let bin="";for(let i=0;i<ab.length;i+=0x8000)bin+=String.fromCharCode(...ab.subarray(i,i+0x8000));return btoa(bin)}throw new Error("image payload missing")}
async function goldRefs(){const paths=["assets/images/star-delta-start-basic/star-delta-start-overview.webp","assets/images/star-delta-start-basic/star-delta-troubleshooting-guide.webp"];const out:any[]=[];for(const p of paths){try{const x=await getRepoFile(p);if(x?.content)out.push({type:"input_image",image_url:`data:image/webp;base64,${String(x.content).replace(/\n/g,"")}`})}catch{}}return out}
async function reviewImage(b64:string,purpose:string,level:string,compareGold=false){const schema={type:"object",additionalProperties:false,required:["pass","score","issues"],properties:{pass:{type:"boolean"},score:{type:"integer",minimum:0,maximum:100},issues:{type:"array",items:{type:"string"}}}};const refs=compareGold?await goldRefs():[];const levelRule=level==="advanced"?"上級記事なので、かわいさより技術的正確性・情報整理・回路/信号/因果関係の明瞭さを優先。キャラクターが主役なら不合格。":"初級〜中級向けなので、親しみやすさと教材としての説明力を両立。";const b=await oa({model:REVIEW_MODEL,store:false,reasoning:{effort:"low"},input:[{role:"user",content:[{type:"input_text",text:`denkicontrol.comの${purpose}画像を実画像ピクセルで審査。${levelRule} 主題の伝わりやすさ、技術的誤り、文字崩れ、情報階層、視線誘導、モバイル可読性、サイト統一感を確認。本文図解は添付のスター・デルタ採用画像をゴールドスタンダードとして、教材として明確に見劣りする場合はpass=false。95点未満はpass=false。`},{type:"input_image",image_url:`data:image/png;base64,${b64}`},...refs]}],text:{format:{type:"json_schema",name:"image_review",strict:true,schema}}});return JSON.parse(outputText(b))}

function sanitizeHtml(s:string){return String(s||"").replace(/<script[\s\S]*?<\/script>/gi,"").replace(/<style[\s\S]*?<\/style>/gi,"").replace(/<iframe[\s\S]*?<\/iframe>/gi,"")}
function replaceOnce(html:string,re:RegExp,repl:string,label:string){if(!re.test(html))throw new Error(`template marker missing: ${label}`);return html.replace(re,repl)}
function safeSlug(s:string,fallback="image"){return String(s||fallback).toLowerCase().replace(/[^a-z0-9-]/g,"-").replace(/-+/g,"-").replace(/^-|-$/g,"")||fallback}

async function blueprint(snap:any){const job=snap.jobs?.[0]??{},research=snap.research?.[0]??{};const sources=Array.isArray(research.sources)?research.sources:[];const coverage={type:"string",enum:["sufficient","partial","missing","unknown"]};const imgItem={type:"object",additionalProperties:false,required:["section_id","slug","purpose","alt","caption","prompt","use_characters"],properties:{section_id:{type:"string"},slug:{type:"string"},purpose:{type:"string",enum:["overview","comparison","process","check-flow","technical"]},alt:{type:"string"},caption:{type:"string"},prompt:{type:"string"},use_characters:{type:"boolean"}}};const schema={type:"object",additionalProperties:false,required:["article_level","level_reason","existing_beginner_coverage","existing_intermediate_coverage","character_density","prerequisite_articles","slug","title","description","og_description","hero_label","hero_lead","summary_cards","toc","sections","conversation","hero_prompt","ogp_prompt","body_images"],properties:{article_level:{type:"string",enum:["beginner","intermediate","advanced"]},level_reason:{type:"string"},existing_beginner_coverage:coverage,existing_intermediate_coverage:coverage,character_density:{type:"string",enum:["high","medium","low"]},prerequisite_articles:{type:"array",items:{type:"string"},maxItems:8},slug:{type:"string"},title:{type:"string"},description:{type:"string"},og_description:{type:"string"},hero_label:{type:"string"},hero_lead:{type:"string"},summary_cards:{type:"array",minItems:3,maxItems:3,items:{type:"object",additionalProperties:false,required:["title","items"],properties:{title:{type:"string"},items:{type:"array",minItems:2,maxItems:4,items:{type:"string"}}}}},toc:{type:"array",minItems:5,maxItems:12,items:{type:"object",additionalProperties:false,required:["id","label"],properties:{id:{type:"string"},label:{type:"string"}}}},sections:{type:"array",minItems:5,maxItems:12,items:{type:"object",additionalProperties:false,required:["id","heading","html"],properties:{id:{type:"string"},heading:{type:"string"},html:{type:"string"}}}},conversation:{type:"object",additionalProperties:false,required:["senpai","kouhai"],properties:{senpai:{type:"string"},kouhai:{type:"string"}}},hero_prompt:{type:"string"},ogp_prompt:{type:"string"},body_images:{type:"array",minItems:1,maxItems:5,items:imgItem}}};
const prompt=`denkicontrol.comの日本語新規記事を設計する。新規記事を初心者向けに固定してはいけない。記事テーマ、既存カバレッジ情報、週次方針を見て beginner / intermediate / advanced を選ぶ。初級の土台が十分なら中級を優先し、上級は前提となる初級・中級知識があるテーマで選ぶ。\n\nレベル別方針:\n- beginner: 用語・基本原理・最初の判断。先輩/後輩キャラクターを多用してよい。本文主要図解2〜5枚。\n- intermediate: 選定・設計・仕様比較・トラブル切り分け・実務判断。キャラクターを多用してよいが、図解の主役は技術内容。本文主要図解2〜5枚。\n- advanced: 応用設計、複数機器連携、制御方式比較、性能/安全設計、故障解析、改善設計。トーンを真剣にし、character_density=low。キャラクターは原則補助、本文主要図解は回路・信号・タイミング・構造・因果関係を優先し1〜4枚。\n\n画像はスター・デルタ記事の採用画像群をゴールドスタンダードとし、文字カードや雰囲気背景ではなく、比較・原理・手順・切り分けを一目で理解できる教材インフォグラフィックを設計する。数値表はHTMLに残してよい。各body_imagesは該当section_idへ挿入する。画像内文字は短く大きくし、日本語の文字崩れが起きにくい構成にする。\n\n技術根拠は日本語公式資料を最優先。具体的な端子番号・線色・配線・安全規格は公式資料で確認できない限り書かない。記事内に主要公式URLを載せる。HTML断片にscript/style/iframeを入れない。\n\n案件:${JSON.stringify(job)}\n調査:${JSON.stringify(research)}\n公式URL:${JSON.stringify(sources.map((s:any)=>({title:s.title,url:s.url,published_or_revised:s.published_or_revised,notes:s.notes})))}`;
const b=await oa({model:TEXT_MODEL,store:false,reasoning:{effort:"medium"},input:prompt,text:{format:{type:"json_schema",name:"article_blueprint_v4",strict:true,schema}}});const x=JSON.parse(outputText(b));x.slug=safeSlug(x.slug,"article");const ids=new Set((x.sections||[]).map((s:any)=>String(s.id)));x.body_images=(Array.isArray(x.body_images)?x.body_images:[]).filter((im:any)=>ids.has(String(im.section_id))).map((im:any,i:number)=>({...im,slug:safeSlug(im.slug,`figure-${i+1}`)}));if(x.article_level!=="advanced"&&x.body_images.length<2)throw new Error("beginner/intermediate article requires at least 2 body images");if(x.article_level==="advanced")x.character_density="low";return x}

function bodyFigure(articleSlug:string,im:any){return `<figure class="article-figure"><div class="article-figure-inner"><img src="../assets/images/${esc(articleSlug)}/${esc(articleSlug)}-${esc(im.slug)}.png" alt="${esc(im.alt)}" loading="lazy" decoding="async"></div><figcaption>${esc(im.caption)}</figcaption></figure>`}
function buildHtml(template:string,b:any,research:any){const slug=b.slug,title=b.title,desc=b.description,og=b.og_description;let h=template.replaceAll(SOURCE_SLUG,slug);h=replaceOnce(h,/<title>[\s\S]*?<\/title>/i,`<title>${esc(title)}</title>`,`title`);h=replaceOnce(h,/<meta content="[^"]*" name="description"\/>/i,`<meta content="${esc(desc)}" name="description"/>`,`description`);h=h.replace(/<meta content="[^"]*" property="og:title"\/>/i,`<meta content="${esc(title)}" property="og:title"/>`).replace(/<meta content="[^"]*" property="og:description"\/>/i,`<meta content="${esc(og)}" property="og:description"/>`).replace(/<meta content="[^"]*" name="twitter:title"\/>/i,`<meta content="${esc(title)}" name="twitter:title"/>`).replace(/<meta content="[^"]*" name="twitter:description"\/>/i,`<meta content="${esc(og)}" name="twitter:description"/>`);if(/<meta[^>]+name="robots"/i.test(h))h=h.replace(/<meta[^>]+name="robots"[^>]*>/i,'<meta name="robots" content="noindex,nofollow">');else h=h.replace(/<title>/i,'<meta name="robots" content="noindex,nofollow">\n<title>');h=h.replace(/<nav class="breadcrumb">[\s\S]*?<\/nav>/i,`<nav class="breadcrumb"><a href="../">ホーム</a><span>›</span><a href="../categories/control-basics.html">制御の基礎</a><span>›</span><span>${esc(title)}</span></nav>`);const hero=`<section class="article-hero"><div class="article-hero-copy"><span class="hero-label">${esc(b.hero_label)}</span><h1>${esc(title)}</h1><p class="hero-lead">${esc(b.hero_lead)}</p><div class="hero-actions"><a class="btn btn-primary" href="#${esc(b.toc[0]?.id||"overview")}">本文から読む</a><a class="btn btn-secondary" href="#summary">先に要点を見る</a></div></div></section>`;h=replaceOnce(h,/<section class="article-hero">[\s\S]*?<\/section>/i,hero,"hero");const cls=["summary-card--fit","summary-card--notyet","summary-card--conclusion"];const sum=`<section aria-label="この記事の要点" class="top-summary" id="summary">${b.summary_cards.map((c:any,i:number)=>`<div class="summary-card ${cls[i]}"><h2>${esc(c.title)}</h2><ul>${c.items.map((v:any)=>`<li>${esc(v)}</li>`).join("")}</ul></div>`).join("")}</section>`;h=replaceOnce(h,/<section aria-label="この記事の要点" class="top-summary" id="summary">[\s\S]*?<\/section>/i,sum,"summary");const toc=`<section aria-label="記事内メニュー" class="mini-toc-card"><h2>この記事でわかること</h2><div class="mini-toc">${b.toc.map((x:any)=>`<a href="#${esc(x.id)}">${esc(x.label)}</a>`).join("")}</div></section>`;h=replaceOnce(h,/<section aria-label="記事内メニュー" class="mini-toc-card">[\s\S]*?<\/section>/i,toc,"toc");const imgs=Array.isArray(b.body_images)?b.body_images:[];const sections=b.sections.map((s:any)=>{const figs=imgs.filter((im:any)=>String(im.section_id)===String(s.id)).map((im:any)=>bodyFigure(slug,im)).join("\n");return `<section class="section-card" id="${esc(s.id)}"><h2>${esc(s.heading)}</h2>${sanitizeHtml(s.html)}${figs}</section>`}).join("\n");let talk="";if(b.article_level==="advanced"){talk=`<section class="section-card"><h2>設計上の要点</h2><div class="talk-thread"><div class="talk-row"><div class="talk-avatar"><img src="../assets/images/guide-characters/friendly_worker_with_helmet_and_smile.png" alt="先輩の案内役"></div><div class="talk-bubble"><p><span class="talk-name talk-name--senpai">先輩</span>${esc(b.conversation.senpai)}</p></div></div></div></section>`}else{talk=`<section class="section-card"><h2>先輩・後輩で確認</h2><div class="talk-thread"><div class="talk-row"><div class="talk-avatar"><img src="../assets/images/guide-characters/friendly_worker_with_helmet_and_smile.png" alt="先輩の案内役"></div><div class="talk-bubble"><p><span class="talk-name talk-name--senpai">先輩</span>${esc(b.conversation.senpai)}</p></div></div><div class="talk-row talk-row--right"><div class="talk-avatar"><img src="../assets/images/guide-characters/curious_worker_with_a_cheerful_expression.png" alt="後輩の案内役"></div><div class="talk-bubble"><p><span class="talk-name talk-name--kouhai">後輩</span>${esc(b.conversation.kouhai)}</p></div></div></div></section>`}const srcs=Array.isArray(research?.sources)?research.sources:[];const refs=`<section class="section-card" id="references"><h2>公式参照資料</h2><ul class="simple-list">${srcs.filter((s:any)=>String(s.url||"").startsWith("https://")).map((s:any)=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title||s.url)}</a>${s.published_or_revised?` — ${esc(s.published_or_revised)}`:""}</li>`).join("")}</ul><p>型式固有の配線・端子・設定は、実機の型式とメーカー公式の最新取扱説明書を照合してください。</p></section>`;const inner=`${sections}\n${talk}\n${refs}`;h=replaceOnce(h,/(<div class="page-layout"><article class="main-column">)[\s\S]*?(<\/article>)/i,`$1\n${inner}\n$2`,`main article`);if(!h.includes(`../assets/images/${slug}/${slug}-hero.png`))throw new Error("hero path audit failed");for(const marker of ["site-header","header-search","language-menu","breadcrumb","page-layout","side-rail","support","related-grid","talk-thread"]){if(!h.includes(marker))throw new Error(`shared structure audit failed: ${marker}`)}return h}

Deno.serve(async req=>{if(req.method==="OPTIONS")return new Response(null,{status:204,headers:H});if(req.method!=="POST")return J({error:"method not allowed"},405);const raw=req.headers.get("authorization")??"";if(!raw.toLowerCase().startsWith("bearer "))return J({error:"authentication required"},401);let input:any={};try{input=await req.json()}catch{return J({error:"invalid json"},400)}const id=String(input.command_id??"");if(!/^[0-9a-f-]{36}$/i.test(id))return J({error:"valid command_id required"},400);let stage="start",st:any={};try{const claimed=await rpc(raw,"ai_editorial_builder_claim",{p_command_id:id,p_lease_seconds:150});if(!claimed?.claimed)return J({ok:true,skipped:true,reason:claimed?.reason,stage:claimed?.stage,status:claimed?.status});stage=String(claimed.stage||"start");st=claimed.state&&typeof claimed.state==="object"?claimed.state:{};const snap=await rpc(raw,"ai_editorial_resume_snapshot",{p_command_id:id});if(String(snap.command?.status)!=="building")return J({ok:true,skipped:true,status:snap.command?.status});if(!GH){await checkpoint(raw,id,stage,{...st,last_error:"GITHUB_REPO_TOKEN missing"});await event(raw,id,"builder-config-missing","GitHub書き込み用トークンが未設定です。同じ案件を保持したまま設定待ちです。","BUILDING","high");return J({ok:false,error:"GITHUB_REPO_TOKEN missing"},503)}

if(stage==="start"){await event(raw,id,"article-blueprint-start","Article Builder v4を起動。既存カバレッジを踏まえて記事レベル・本文図解・キャラクター密度を設計します。");const bp=await blueprint(snap);const branch=`ai-editorial/article-${id.slice(0,8)}`,articlePath=`articles/${bp.slug}.html`;st={...st,bp,branch,article_path:articlePath,hero_attempt:0,ogp_attempt:0,body_index:0,body_attempts:{},body_scores:{},body_issues:{},errors:{}};await checkpoint(raw,id,"blueprint_done",st);await event(raw,id,"article-blueprint-done",`本文設計が完了しました。難易度=${bp.article_level}、本文図解=${bp.body_images.length}枚、キャラクター密度=${bp.character_density}で制作します。`);return J({ok:true,next:"blueprint_done",article_level:bp.article_level,body_images:bp.body_images.length})}

if(stage==="blueprint_done"){const bp=st.bp;if(!bp)throw new Error("checkpoint blueprint missing");const template=await getTemplate(),research=snap.research?.[0]??{},html=buildHtml(template,bp,research);await ensureBranch(st.branch);await putFile(st.branch,st.article_path,utf8ToB64(html),`AI編集部: ${bp.title}`);st={...st,html_written:true};await checkpoint(raw,id,"html_written",st);await event(raw,id,"article-html-written","記事HTMLを保存しました。次にhero実画像を生成・実物監査します。","BUILDING","info",[{kind:"github-branch",ref:st.branch}]);return J({ok:true,next:"html_written"})}

if(stage==="html_written"||stage==="hero_retry"){const bp=st.bp,attempt=Number(st.hero_attempt||0)+1;if(!bp)throw new Error("checkpoint blueprint missing");let prompt=`${bp.hero_prompt}\nDenkicontrolの技術記事hero。実在メーカーのロゴ・UI・型式銘板は描かない。重要要素は右側、左側はHTML見出し用の余白。記事レベル=${bp.article_level}。`;if(bp.article_level==="advanced")prompt+="上級向けなので落ち着いた技術資料調、キャラクターは原則不要。";if(Array.isArray(st.hero_issues)&&st.hero_issues.length)prompt+=`\n前回指摘: ${st.hero_issues.join(" / ")}`;await event(raw,id,"hero-generation",`hero実画像を生成しています（${attempt}/3）。`);const b64=await makeImage(prompt),review=await reviewImage(b64,"hero",bp.article_level,false);st={...st,hero_attempt:attempt,hero_score:review.score,hero_issues:review.issues||[]};if(!(review.pass&&Number(review.score)>=95)&&attempt<3){await checkpoint(raw,id,"hero_retry",st);await event(raw,id,"hero-review-retry",`hero監査 ${review.score}点。95点未達のため再生成します。`);return J({ok:true,next:"hero_retry",score:review.score})}await putFile(st.branch,`assets/images/${bp.slug}/${bp.slug}-hero.png`,b64,`Add reviewed hero for ${bp.slug}`);await checkpoint(raw,id,"hero_done",st);const heroPass=Boolean(review.pass)&&Number(review.score)>=95;await event(raw,id,heroPass?"hero-review-pass":"hero-review-degraded-continue",heroPass?`hero実画像の監査を通過しました（${review.score}点）。次に本文図解を生成します。`:`hero監査は3回目も${review.score}点で基準未達です。途中停止せず暫定候補を保存し、最終Preview監査でページ全体として再評価します。`,"BUILDING",heroPass?"info":"medium");return J({ok:true,next:"hero_done",score:review.score,degraded:!heroPass})}

if(stage==="hero_done"||stage==="body_retry"||stage==="body_next"){const bp=st.bp;if(!bp)throw new Error("checkpoint blueprint missing");const list=Array.isArray(bp.body_images)?bp.body_images:[],idx=Number(st.body_index||0);if(idx>=list.length){await checkpoint(raw,id,"body_done",st);await event(raw,id,"body-images-done",`本文図解 ${list.length}枚の生成・実物監査が完了しました。次にOGPを生成します。`);return J({ok:true,next:"body_done"})}const im=list[idx],attempts={...(st.body_attempts||{})},attempt=Number(attempts[idx]||0)+1;let prompt=`${im.prompt}\nDenkicontrolの本文教材インフォグラフィック。用途=${im.purpose}。記事レベル=${bp.article_level}。白背景・青系中心、必要に応じて緑・橙・紫・赤を補助色。タイトル→主図→要点/手順→注意の情報階層。スター・デルタ採用画像と同等以上の教材説明力を目標にする。長文を詰め込まず、短い日本語ラベルを大きく。実在ロゴ・UIは禁止。`;if(bp.article_level==="advanced")prompt+="上級向け。キャラクターは原則使わず、回路・信号・タイミング・構造・因果関係を主役にした真剣な技術図解。";else if(im.use_characters)prompt+="先輩・後輩は案内役として使ってよいが、図解より目立たせない。";const prior=st.body_issues?.[idx];if(Array.isArray(prior)&&prior.length)prompt+=`\n前回指摘: ${prior.join(" / ")}`;await event(raw,id,"body-image-generation",`本文図解 ${idx+1}/${list.length}「${im.purpose}」を生成しています（${attempt}/3）。`);const b64=await makeImage(prompt),review=await reviewImage(b64,`本文図解 ${im.purpose}`,bp.article_level,true);attempts[idx]=attempt;const scores={...(st.body_scores||{}),[idx]:review.score},issues={...(st.body_issues||{}),[idx]:review.issues||[]};st={...st,body_attempts:attempts,body_scores:scores,body_issues:issues};if(!(review.pass&&Number(review.score)>=95)&&attempt<3){await checkpoint(raw,id,"body_retry",st);await event(raw,id,"body-image-review-retry",`本文図解 ${idx+1}/${list.length} は ${review.score}点。ゴールドスタンダード未達のため再生成します。`);return J({ok:true,next:"body_retry",index:idx,score:review.score})}await putFile(st.branch,`assets/images/${bp.slug}/${bp.slug}-${im.slug}.png`,b64,`Add reviewed article figure ${im.slug}`);st={...st,body_index:idx+1};await checkpoint(raw,id,"body_next",st);const bodyPass=Boolean(review.pass)&&Number(review.score)>=95;await event(raw,id,bodyPass?"body-image-review-pass":"body-image-review-degraded-continue",bodyPass?`本文図解 ${idx+1}/${list.length} の実物監査を通過しました（${review.score}点）。`:`本文図解 ${idx+1}/${list.length} は3回目も${review.score}点で基準未達です。途中停止せず暫定候補を保存し、最終Preview監査でページ全体として再評価します。`,"BUILDING",bodyPass?"info":"medium");return J({ok:true,next:"body_next",index:idx+1,score:review.score,degraded:!bodyPass})}

if(stage==="body_done"||stage==="ogp_retry"){const bp=st.bp;if(!bp)throw new Error("checkpoint blueprint missing");const attempt=Number(st.ogp_attempt||0)+1;let prompt=`${bp.ogp_prompt}\nOGP用。小さく表示しても主題が伝わる。長文や実在ロゴを入れない。記事レベル=${bp.article_level}。`;if(bp.article_level==="advanced")prompt+="落ち着いた技術資料調で、キャラクターは原則不要。";if(Array.isArray(st.ogp_issues)&&st.ogp_issues.length)prompt+=`\n前回指摘: ${st.ogp_issues.join(" / ")}`;await event(raw,id,"ogp-generation",`OGP実画像を生成しています（${attempt}/3）。`);const b64=await makeImage(prompt),review=await reviewImage(b64,"OGP",bp.article_level,false);st={...st,ogp_attempt:attempt,ogp_score:review.score,ogp_issues:review.issues||[]};if(!(review.pass&&Number(review.score)>=95)&&attempt<3){await checkpoint(raw,id,"ogp_retry",st);await event(raw,id,"ogp-review-retry",`OGP監査 ${review.score}点。95点未達のため再生成します。`);return J({ok:true,next:"ogp_retry",score:review.score})}await putFile(st.branch,`assets/images/${bp.slug}/${bp.slug}-ogp.png`,b64,`Add reviewed OGP for ${bp.slug}`);await checkpoint(raw,id,"images_done",st);await event(raw,id,review.pass&&Number(review.score)>=95?"ogp-review-pass":"ogp-review-degraded-continue",review.pass&&Number(review.score)>=95?`OGP実画像の監査を通過しました（${review.score}点）。PRを作成します。`:`OGPは3回の再生成で${review.score}点でした。ここでは案件を停止せず候補を採用し、最終Previewの専用OGP監査で再設計します。`,"BUILDING",review.pass&&Number(review.score)>=95?"info":"medium");return J({ok:true,next:"images_done",score:review.score})}

if(stage==="images_done"){const bp=st.bp;if(!bp)throw new Error("checkpoint blueprint missing");const pr=await openPr(st.branch,`AI編集部: 新規記事 ${bp.title}`,`AI編集部案件 ${id}\n\n- 正本: ${TEMPLATE}\n- 記事レベル: ${bp.article_level}\n- レベル理由: ${bp.level_reason}\n- キャラクター密度: ${bp.character_density}\n- 本文図解: ${bp.body_images.length}枚（${IMAGE_MODEL}で実生成・実画像監査）\n- 日本語公式資料を優先\n- 共有UI/CSSは正本から継承\n- Step 1: 記事・画像・Previewのみ`);const preview=cloudflarePreview(st.branch,st.article_path);st={...st,pr_number:pr.number,pr_url:pr.html_url,preview_url:preview};await checkpoint(raw,id,"preview_wait",st);await event(raw,id,"pr-created",`GitHub PR #${pr.number} を作成しました。Preview確認は専用Probeへ引き継ぎます。`,"BUILDING","info",[{kind:"github-pr",ref:pr.html_url},{kind:"preview",ref:preview}]);return J({ok:true,next:"preview_wait",pr_url:pr.html_url,preview_url:preview})}

if(stage==="preview_wait")return J({ok:true,waiting:true,stage:"preview_wait",preview_url:st.preview_url});if(stage==="done")return J({ok:true,done:true});throw new Error(`unknown builder stage: ${stage}`)}catch(e){const m=e instanceof Error?e.message:String(e),errors={...(st.errors||{})};errors[stage]=Number(errors[stage]||0)+1;const next={...st,errors,last_error:m.slice(0,1500)};try{await checkpoint(raw,id,stage,next);await event(raw,id,"article-builder-error",`Article Builder v4の「${stage}」工程で停止: ${m.slice(0,400)}。同じ案件・同じ工程から再試行します。`,"BUILDING","high")}catch{}if(Number(errors[stage])>=3){try{await patch(raw,id,"failed",m)}catch{}}return J({ok:false,error:m,stage,retry_count:errors[stage]},500)}});
